import {parsePhotoDevelop,serializePhotoDevelop,validatePhotoDevelop,type PhotoDevelopSettings} from '@/components/nyc-tron/ui/components/forge/photo/photo-adjustments';
export interface PhotoPreset {readonly version:1;readonly id:string;readonly name:string;readonly settings:PhotoDevelopSettings}
export function validatePhotoPreset(preset:PhotoPreset):void {if(preset.version!==1||typeof preset.id!=='string'||!preset.id.trim()||preset.id.length>256||typeof preset.name!=='string'||!preset.name.trim()||preset.name.length>256)throw new TypeError('Photo preset requires version 1, identity and name');validatePhotoDevelop(preset.settings);}
export function validatePhotoPresets(presets:readonly PhotoPreset[]):void {if(presets.length>2000)throw new RangeError('Preset library exceeds 2,000 entries');const ids=new Set<string>();for(const preset of presets){validatePhotoPreset(preset);if(ids.has(preset.id))throw new TypeError('Duplicate photo preset identity');ids.add(preset.id);}}
export function serializePhotoPreset(preset:PhotoPreset):string {validatePhotoPreset(preset);return JSON.stringify({version:1,id:preset.id,name:preset.name,settings:parsePhotoDevelop(serializePhotoDevelop(preset.settings))});}
export function parsePhotoPreset(text:string):PhotoPreset {if(typeof text!=='string'||text.length>131072)throw new RangeError('Photo preset payload exceeds 128 KiB');const value=JSON.parse(text) as PhotoPreset;validatePhotoPreset(value);return JSON.parse(serializePhotoPreset(value)) as PhotoPreset;}
export function validatePhotoTargets(ids:readonly string[]):void {if(ids.length>10000||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!id.trim()||id.length>256))throw new TypeError('Photo targets require at most 10,000 unique identities');}
